    /** Evaluates [predicate] with the domain's single implementation [predicates]. */
    @Suppress("CyclomaticComplexMethod")
    fun holds(
        predicate: CreditClaimPredicate,
        predicates: CreditClaimPredicates,
        facts: CreditClaimFacts,
    ): Boolean =
        when (predicate) {
            CreditClaimPredicate.COVERAGE_ACTIVE -> predicates.coverageActive(facts)
            CreditClaimPredicate.PRE_APPROVAL_REQUEST_COMPLETE -> predicates.preApprovalRequestComplete(facts)
            CreditClaimPredicate.PAYER_QUERY_RECORDED -> predicates.payerQueryRecorded(facts)
            CreditClaimPredicate.QUERY_RESPONSE_COMPLETE -> predicates.queryResponseComplete(facts)
            CreditClaimPredicate.QUERY_ON_PRE_APPROVAL -> predicates.queryOnPreApproval(facts)
            CreditClaimPredicate.QUERY_ON_ENHANCEMENT -> predicates.queryOnEnhancement(facts)
            CreditClaimPredicate.QUERY_ON_DISCHARGE_AUTH -> predicates.queryOnDischargeAuth(facts)
            CreditClaimPredicate.QUERY_ON_CLAIM -> predicates.queryOnClaim(facts)
            CreditClaimPredicate.QUERY_NOT_ON_CLAIM -> predicates.queryNotOnClaim(facts)
            CreditClaimPredicate.APPROVAL_TERMS_RECORDED -> predicates.approvalTermsRecorded(facts)
            CreditClaimPredicate.ENHANCEMENT_REQUEST_COMPLETE -> predicates.enhancementRequestComplete(facts)
            CreditClaimPredicate.ENHANCEMENT_APPROVED_BEFORE -> predicates.enhancementApprovedBefore(facts)
            CreditClaimPredicate.NO_ENHANCEMENT_APPROVED_BEFORE -> predicates.noEnhancementApprovedBefore(facts)
            CreditClaimPredicate.CLINICAL_DISCHARGE_RECORDED -> predicates.clinicalDischargeRecorded(facts)
            CreditClaimPredicate.DISCHARGE_AUTH_REQUEST_COMPLETE -> predicates.dischargeAuthRequestComplete(facts)
            CreditClaimPredicate.EVERY_LINE_WITHIN_PRE_APPROVAL_OR_FLAGGED -> predicates.everyLineWithinPreApprovalOrFlagged(facts)
            CreditClaimPredicate.FINAL_APPROVAL_TERMS_RECORDED -> predicates.finalApprovalTermsRecorded(facts)
            CreditClaimPredicate.CLAIM_PACK_COMPLETE -> predicates.claimPackComplete(facts)
            CreditClaimPredicate.SETTLEMENT_RECORDED -> predicates.settlementRecorded(facts)
            CreditClaimPredicate.SETTLED_IN_FULL -> predicates.settledInFull(facts)
            CreditClaimPredicate.SETTLED_SHORT -> predicates.settledShort(facts)
            CreditClaimPredicate.DEDUCTION_REASONS_RECORDED -> predicates.deductionReasonsRecorded(facts)
            CreditClaimPredicate.DENIAL_REASONS_RECORDED -> predicates.denialReasonsRecorded(facts)
            CreditClaimPredicate.APPEAL_GROUNDS_RECORDED -> predicates.appealGroundsRecorded(facts)
            CreditClaimPredicate.APPEAL_WITHIN_DEADLINE -> predicates.appealWithinDeadline(facts)
            CreditClaimPredicate.RECONCILIATION_COMPLETE -> predicates.reconciliationComplete(facts)
            CreditClaimPredicate.WITHDRAWAL_REASON_RECORDED -> predicates.withdrawalReasonRecorded(facts)
            CreditClaimPredicate.PRIVILEGED_AND_AUDITED -> predicates.privilegedAndAudited(facts)
            CreditClaimPredicate.CORRECTION_REASON_ENTERED -> predicates.correctionReasonEntered(facts)
        }

    /** Applies [command] in [state] with [facts]; never changes state unless exactly one guard holds. */
    fun fire(
        state: CreditClaimState,
        command: CreditClaimCommand,
        predicates: CreditClaimPredicates,
        facts: CreditClaimFacts,
    ): Outcome<CreditClaimState, CreditClaimCommand, CreditClaimPredicate, CreditClaimEffect> =
        spec.fire(state, command) { holds(it, predicates, facts) }
}
